INSERT INTO experiment_reports (report_id, title, content, author, create_at, update_at, experiment_date, hypothesis, result_summary) VALUES
    (1, '클래스 가중치 적용에 따른 소수 클래스 재현율 실험', '실험 목적: 클래스 가중치 적용에 따른 소수 클래스 재현율 실험의 영향을 객관적으로 확인한다. 환경: 불균형 데이터 12:6:3. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 class_weight 적용 전후 Macro-F1를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 소수 클래스 누락 여부를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-02', '클래스 가중치 적용에 따른 소수 클래스 재현율 실험에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'class_weight 적용 전후 Macro-F1를 기준으로 비교하고 소수 클래스 누락 여부를 재확인한다.'),
    (2, '학습률 변화에 따른 CNN 수렴 속도 비교', '실험 목적: 학습률 변화에 따른 CNN 수렴 속도 비교의 영향을 객관적으로 확인한다. 환경: 32×32 컬러 이미지. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 SGD 0.01·0.001 비교를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 검증 손실 변동를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-03', '학습률 변화에 따른 CNN 수렴 속도 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'SGD 0.01·0.001 비교를 기준으로 비교하고 검증 손실 변동를 재확인한다.'),
    (3, 'AdamW와 SGD의 일반화 성능 비교', '실험 목적: AdamW와 SGD의 일반화 성능 비교의 영향을 객관적으로 확인한다. 환경: 동일 분할과 초기 Seed. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 동일 epoch의 검증 정확도를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 옵티마이저 공정 비교를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-04', 'AdamW와 SGD의 일반화 성능 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', '동일 epoch의 검증 정확도를 기준으로 비교하고 옵티마이저 공정 비교를 재확인한다.'),
    (4, '배치 크기 변화가 학습 안정성에 미치는 영향', '실험 목적: 배치 크기 변화가 학습 안정성에 미치는 영향의 영향을 객관적으로 확인한다. 환경: batch 4·8·16. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 epoch별 손실 분산를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 속도와 일반화 균형를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-05', '배치 크기 변화가 학습 안정성에 미치는 영향에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'epoch별 손실 분산를 기준으로 비교하고 속도와 일반화 균형를 재확인한다.'),
    (5, '데이터 증강 회전과 좌우 반전 효과', '실험 목적: 데이터 증강 회전과 좌우 반전 효과의 영향을 객관적으로 확인한다. 환경: 형상 이미지 분류. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 증강 적용 전후 recall를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 의미를 바꾸는 flip 주의를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-06', '데이터 증강 회전과 좌우 반전 효과에서 비교 조건을 통제하면 차이가 나타날 것이다.', '증강 적용 전후 recall를 기준으로 비교하고 의미를 바꾸는 flip 주의를 재확인한다.'),
    (6, '조기 종료 조건에 따른 과적합 방지', '실험 목적: 조기 종료 조건에 따른 과적합 방지의 영향을 객관적으로 확인한다. 환경: train/valid 손실 추적. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 patience 2·4 비교를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 최적 체크포인트 복원를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-07', '조기 종료 조건에 따른 과적합 방지에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'patience 2·4 비교를 기준으로 비교하고 최적 체크포인트 복원를 재확인한다.'),
    (7, 'ResNet18 전이학습과 소형 CNN 성능 비교', '실험 목적: ResNet18 전이학습과 소형 CNN 성능 비교의 영향을 객관적으로 확인한다. 환경: 사전학습 가중치 사용. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 Macro-F1와 추론 시간를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 전처리 계약 유지를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-08', 'ResNet18 전이학습과 소형 CNN 성능 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'Macro-F1와 추론 시간를 기준으로 비교하고 전처리 계약 유지를 재확인한다.'),
    (8, '다중 클래스 ROC 해석 방법 실험', '실험 목적: 다중 클래스 ROC 해석 방법 실험의 영향을 객관적으로 확인한다. 환경: 세 클래스 확률 출력. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 one-vs-rest AUC를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 임계값과 AUC 구분를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-09', '다중 클래스 ROC 해석 방법 실험에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'one-vs-rest AUC를 기준으로 비교하고 임계값과 AUC 구분를 재확인한다.'),
    (9, '정규화 범위와 모델 입력 분포 비교', '실험 목적: 정규화 범위와 모델 입력 분포 비교의 영향을 객관적으로 확인한다. 환경: 픽셀 입력 0~255. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 0~1 및 ImageNet Normalize를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 학습과 배포 전처리 일치를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-10', '정규화 범위와 모델 입력 분포 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', '0~1 및 ImageNet Normalize를 기준으로 비교하고 학습과 배포 전처리 일치를 재확인한다.'),
    (10, 'Transformer 마스킹 유무 비교', '실험 목적: Transformer 마스킹 유무 비교의 영향을 객관적으로 확인한다. 환경: 가변 길이 문장. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 key_padding_mask 유무를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 패딩 위치 영향를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-11', 'Transformer 마스킹 유무 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'key_padding_mask 유무를 기준으로 비교하고 패딩 위치 영향를 재확인한다.'),
    (11, 'RNN과 LSTM의 장기 의존성 비교', '실험 목적: RNN과 LSTM의 장기 의존성 비교의 영향을 객관적으로 확인한다. 환경: 길이 8·16 시계열. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 예측오차의 추세를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 입력 Shape 확인를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-12', 'RNN과 LSTM의 장기 의존성 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', '예측오차의 추세를 기준으로 비교하고 입력 Shape 확인를 재확인한다.'),
    (12, '오토인코더 잠재 차원 축소 비교', '실험 목적: 오토인코더 잠재 차원 축소 비교의 영향을 객관적으로 확인한다. 환경: 8개 길이 윈도우. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 latent 1·2·4 복원오차를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 과도한 압축 문제를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-13', '오토인코더 잠재 차원 축소 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'latent 1·2·4 복원오차를 기준으로 비교하고 과도한 압축 문제를 재확인한다.'),
    (13, 'Gradient Clipping 학습 안정성 실험', '실험 목적: Gradient Clipping 학습 안정성 실험의 영향을 객관적으로 확인한다. 환경: 순환신경망 손실. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 clip_norm 0.5·1.0를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 기울기 폭주 확인를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-14', 'Gradient Clipping 학습 안정성 실험에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'clip_norm 0.5·1.0를 기준으로 비교하고 기울기 폭주 확인를 재확인한다.'),
    (14, '가중치 초기화가 학습 수렴에 미치는 영향', '실험 목적: 가중치 초기화가 학습 수렴에 미치는 영향의 영향을 객관적으로 확인한다. 환경: 동일 모델 구조. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 Kaiming 초기화 비교를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: seed 재현성를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-15', '가중치 초기화가 학습 수렴에 미치는 영향에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'Kaiming 초기화 비교를 기준으로 비교하고 seed 재현성를 재확인한다.'),
    (15, 'L2 정규화가 회귀 오차에 미치는 영향', '실험 목적: L2 정규화가 회귀 오차에 미치는 영향의 영향을 객관적으로 확인한다. 환경: 요청 처리 시간 예측. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 alpha 0·0.1·1를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 편향·분산 변화를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-16', 'L2 정규화가 회귀 오차에 미치는 영향에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'alpha 0·0.1·1를 기준으로 비교하고 편향·분산 변화를 재확인한다.'),
    (16, '결측값 대체 전략별 분류 성능 비교', '실험 목적: 결측값 대체 전략별 분류 성능 비교의 영향을 객관적으로 확인한다. 환경: 수치형 누락 필드. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 중앙값·최빈값를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 학습 데이터로만 fit를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-17', '결측값 대체 전략별 분류 성능 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', '중앙값·최빈값를 기준으로 비교하고 학습 데이터로만 fit를 재확인한다.'),
    (17, '범주형 인코딩에 따른 차원 변화', '실험 목적: 범주형 인코딩에 따른 차원 변화의 영향을 객관적으로 확인한다. 환경: 작업 유형 필드. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 OneHotEncoder 열 수를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 새 범주 처리를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-18', '범주형 인코딩에 따른 차원 변화에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'OneHotEncoder 열 수를 기준으로 비교하고 새 범주 처리를 재확인한다.'),
    (18, '교차검증 Fold 구성의 영향', '실험 목적: 교차검증 Fold 구성의 영향의 영향을 객관적으로 확인한다. 환경: 소규모 표본 데이터. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 3-Fold·5-Fold 편차를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 데이터 누수 방지를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-01', '교차검증 Fold 구성의 영향에서 비교 조건을 통제하면 차이가 나타날 것이다.', '3-Fold·5-Fold 편차를 기준으로 비교하고 데이터 누수 방지를 재확인한다.'),
    (19, 'Depth 제한이 결정트리 성능에 미치는 영향', '실험 목적: Depth 제한이 결정트리 성능에 미치는 영향의 영향을 객관적으로 확인한다. 환경: 테이블 분류 데이터. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 max_depth 2·5를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 학습·검증 격차를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-02', 'Depth 제한이 결정트리 성능에 미치는 영향에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'max_depth 2·5를 기준으로 비교하고 학습·검증 격차를 재확인한다.'),
    (20, '클래스 확률 임계값에 따른 정밀도 변화', '실험 목적: 클래스 확률 임계값에 따른 정밀도 변화의 영향을 객관적으로 확인한다. 환경: 불균형 이진 분류. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 Precision·Recall 표를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 운영 목표별 선택를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-03', '클래스 확률 임계값에 따른 정밀도 변화에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'Precision·Recall 표를 기준으로 비교하고 운영 목표별 선택를 재확인한다.'),
    (21, 'OCR PSM 모드에 따른 추출 품질 비교', '실험 목적: OCR PSM 모드에 따른 추출 품질 비교의 영향을 객관적으로 확인한다. 환경: 표와 문단 혼합 이미지. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 PSM 3·6 추출 차이를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 행 순서 안정성를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-04', 'OCR PSM 모드에 따른 추출 품질 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'PSM 3·6 추출 차이를 기준으로 비교하고 행 순서 안정성를 재확인한다.'),
    (22, 'YOLO confidence 임계값 조정 실험', '실험 목적: YOLO confidence 임계값 조정 실험의 영향을 객관적으로 확인한다. 환경: 검출 이미지 20장. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 오탐·누락 건수를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 탐지 품질 균형를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-05', 'YOLO confidence 임계값 조정 실험에서 비교 조건을 통제하면 차이가 나타날 것이다.', '오탐·누락 건수를 기준으로 비교하고 탐지 품질 균형를 재확인한다.'),
    (23, '이미지 해상도 축소와 추론 속도 비교', '실험 목적: 이미지 해상도 축소와 추론 속도 비교의 영향을 객관적으로 확인한다. 환경: 원본 640×640. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 320·640 크기를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 작은 객체 인식 변화를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-06', '이미지 해상도 축소와 추론 속도 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', '320·640 크기를 기준으로 비교하고 작은 객체 인식 변화를 재확인한다.'),
    (24, '시계열 윈도우 길이별 예측 비교', '실험 목적: 시계열 윈도우 길이별 예측 비교의 영향을 객관적으로 확인한다. 환경: 일별 요청량. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 윈도우 8·12를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 시간축 누수 주의를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-07', '시계열 윈도우 길이별 예측 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', '윈도우 8·12를 기준으로 비교하고 시간축 누수 주의를 재확인한다.'),
    (25, 'Embedding 정규화와 Cosine 검색 비교', '실험 목적: Embedding 정규화와 Cosine 검색 비교의 영향을 객관적으로 확인한다. 환경: 보고서 개요 180건. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 정규화 전후 거리를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 동일 모델 계약를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-08', 'Embedding 정규화와 Cosine 검색 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', '정규화 전후 거리를 기준으로 비교하고 동일 모델 계약를 재확인한다.'),
    (26, 'Top-k 후보 수 변화 검색 적중률 실험', '실험 목적: Top-k 후보 수 변화 검색 적중률 실험의 영향을 객관적으로 확인한다. 환경: 질문·정답 20쌍. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 Recall@1·@5·@10를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 후보 증가의 비용를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-09', 'Top-k 후보 수 변화 검색 적중률 실험에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'Recall@1·@5·@10를 기준으로 비교하고 후보 증가의 비용를 재확인한다.'),
    (27, 'Chunk Overlap 설정별 문맥 보존 평가', '실험 목적: Chunk Overlap 설정별 문맥 보존 평가의 영향을 객관적으로 확인한다. 환경: 길이 350자 문서. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 overlap 0·50·100를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 중복 검색 결과를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-10', 'Chunk Overlap 설정별 문맥 보존 평가에서 비교 조건을 통제하면 차이가 나타날 것이다.', 'overlap 0·50·100를 기준으로 비교하고 중복 검색 결과를 재확인한다.'),
    (28, '프롬프트 길이와 JSON 생성 성공률', '실험 목적: 프롬프트 길이와 JSON 생성 성공률의 영향을 객관적으로 확인한다. 환경: 요약 지시 3종. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 파싱 성공률과 토큰량를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 과도한 지시 제한를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-11', '프롬프트 길이와 JSON 생성 성공률에서 비교 조건을 통제하면 차이가 나타날 것이다.', '파싱 성공률과 토큰량를 기준으로 비교하고 과도한 지시 제한를 재확인한다.'),
    (29, 'Vector 인덱스 HNSW 검색 속도 비교', '실험 목적: Vector 인덱스 HNSW 검색 속도 비교의 영향을 객관적으로 확인한다. 환경: 동일 384차원 벡터. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 정확검색과 ANN 시간를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 후보 정확성 검증를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-12', 'Vector 인덱스 HNSW 검색 속도 비교에서 비교 조건을 통제하면 차이가 나타날 것이다.', '정확검색과 ANN 시간를 기준으로 비교하고 후보 정확성 검증를 재확인한다.'),
    (30, '도구 호출 실패 시 Agent 복구 성능', '실험 목적: 도구 호출 실패 시 Agent 복구 성능의 영향을 객관적으로 확인한다. 환경: 가상 도구 오류 입력. 방법: 동일한 데이터 분할과 기준 모델을 유지하며 완료·실패 응답률를 기록한다. 결과: 각 조건의 측정값을 표로 비교하고 성능 차이의 원인을 논의한다. 해석: 무한 재시도 방지를 확인했으며, 반복 실험 전에는 수치 차이를 단정하지 않는다. 다음 조치: 동일 Seed와 테스트 데이터로 결과를 재검증한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-13', '도구 호출 실패 시 Agent 복구 성능에서 비교 조건을 통제하면 차이가 나타날 것이다.', '완료·실패 응답률를 기준으로 비교하고 무한 재시도 방지를 재확인한다.')
INSERT INTO daily_work_reports (report_id, title, content, author, create_at, update_at, work_date, progress, blockers) VALUES
    (31, 'FastAPI Router 설계 및 엔드포인트 점검', '금일 주요 업무: FastAPI Router 설계 및 엔드포인트 점검. 작업 배경은 라우팅 등록과 기본 응답 확인이며, 수행한 활동은 OpenAPI 경로 8건 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 다음 작업: 요청 검증 추가. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-02', 'OpenAPI 경로 8건 확인 완료, 검토 결과 공유', ''),
    (32, 'PostgreSQL 스키마 초기화 및 권한 점검', '금일 주요 업무: PostgreSQL 스키마 초기화 및 권한 점검. 작업 배경은 실습 DB 생성·접속 확인이며, 수행한 활동은 카테고리 테이블 COUNT 검사이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 기존 데이터 보존. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-03', '카테고리 테이블 COUNT 검사 완료, 검토 결과 공유', ''),
    (33, 'SQLAlchemy Session 흐름 점검', '금일 주요 업무: SQLAlchemy Session 흐름 점검. 작업 배경은 flush/commit/rollback 실험이며, 수행한 활동은 미커밋 데이터 회복 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 세션 범위 명시. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-04', '미커밋 데이터 회복 확인 완료, 검토 결과 공유', ''),
    (34, 'Postman Collection 요청 정리', '금일 주요 업무: Postman Collection 요청 정리. 작업 배경은 요청 환경 변수 통일이며, 수행한 활동은 GET/POST 응답 200·201 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 미완료 오류 시나리오. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-05', 'GET/POST 응답 200·201 확인 완료, 검토 결과 공유', '미완료 오류 시나리오; 조치 예정'),
    (35, '개요 E5 Embedding 배치 생성', '금일 주요 업무: 개요 E5 Embedding 배치 생성. 작업 배경은 모델 캐시 및 CPU 설정이며, 수행한 활동은 384차원 출력 검증이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 재실행 안전성 점검. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-06', '384차원 출력 검증 완료, 검토 결과 공유', ''),
    (36, 'pgvector Cosine 검색 API 연결', '금일 주요 업무: pgvector Cosine 검색 API 연결. 작업 배경은 Vector SELECT 파라미터화이며, 수행한 활동은 동일 질의 Top-k 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 경계값 검토. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-07', '동일 질의 Top-k 확인 완료, 검토 결과 공유', ''),
    (37, 'LLM Client API 키 환경 분리', '금일 주요 업무: LLM Client API 키 환경 분리. 작업 배경은 설정 파일 읽기 확인이며, 수행한 활동은 키 미노출 점검이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 실행 로그 마스킹. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-08', '키 미노출 점검 완료, 검토 결과 공유', ''),
    (38, 'LLM Timeout 예외 대응 정리', '금일 주요 업무: LLM Timeout 예외 대응 정리. 작업 배경은 테스트 타임아웃 재현이며, 수행한 활동은 504 반환 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 재시도 제한 검토. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-09', '504 반환 확인 완료, 검토 결과 공유', '재시도 제한 검토; 조치 예정'),
    (39, '프롬프트 JSON Schema 변경 검토', '금일 주요 업무: 프롬프트 JSON Schema 변경 검토. 작업 배경은 Pydantic 필드 정의이며, 수행한 활동은 검증 실패 입력 목록 작성이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 시연용 케이스 정리. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-10', '검증 실패 입력 목록 작성 완료, 검토 결과 공유', ''),
    (40, '보고서 분류 코드와 매핑 검증', '금일 주요 업무: 보고서 분류 코드와 매핑 검증. 작업 배경은 6개 카테고리 입력이며, 수행한 활동은 종류별 상세 행 검사이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 유효성 에러 대응. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-11', '종류별 상세 행 검사 완료, 검토 결과 공유', ''),
    (41, '원문 텍스트 UTF-8 인코딩 확인', '금일 주요 업무: 원문 텍스트 UTF-8 인코딩 확인. 작업 배경은 한글과 특수문자 입력이며, 수행한 활동은 바이트 길이 비교이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 손상 파일 검토. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-12', '바이트 길이 비교 완료, 검토 결과 공유', ''),
    (42, '문서 Parsing 오류 기록 정리', '금일 주요 업무: 문서 Parsing 오류 기록 정리. 작업 배경은 빈 PDF와 텍스트 PDF 구분이며, 수행한 활동은 needs_ocr 상태 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: OCR 도구 준비. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-13', 'needs_ocr 상태 확인 완료, 검토 결과 공유', 'OCR 도구 준비; 조치 예정'),
    (43, 'Chunk 위치 정보 테스트 보완', '금일 주요 업무: Chunk 위치 정보 테스트 보완. 작업 배경은 원본 텍스트 인덱스 계산이며, 수행한 활동은 Span 본문 일치 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 경계 사례 추가. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-14', 'Span 본문 일치 확인 완료, 검토 결과 공유', ''),
    (44, '미수집 자료 Manifest 점검', '금일 주요 업무: 미수집 자료 Manifest 점검. 작업 배경은 원본 SHA-256 재계산이며, 수행한 활동은 중복 파일 목록 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 수집 규칙 수정. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-15', '중복 파일 목록 확인 완료, 검토 결과 공유', ''),
    (45, '테스트용 기초 데이터 180건 검수', '금일 주요 업무: 테스트용 기초 데이터 180건 검수. 작업 배경은 종류별 30건 카운트이며, 수행한 활동은 FK 누락 0건 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 본문 품질 점검. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-16', 'FK 누락 0건 확인 완료, 검토 결과 공유', ''),
    (46, '검색어 가중치 테스트 케이스 정리', '금일 주요 업무: 검색어 가중치 테스트 케이스 정리. 작업 배경은 정확·유사·무관 질의 작성이며, 수행한 활동은 검색 후보 표 수집이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 오탐 사례 검토. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-17', '검색 후보 표 수집 완료, 검토 결과 공유', '오탐 사례 검토; 조치 예정'),
    (47, 'CRUD DELETE 연쇄 삭제 검증', '금일 주요 업무: CRUD DELETE 연쇄 삭제 검증. 작업 배경은 테스트 보고서 생성이며, 수행한 활동은 상세·벡터 삭제 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 원본 seed 유지. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-18', '상세·벡터 삭제 확인 완료, 검토 결과 공유', ''),
    (48, '제목 부분 검색 LIKE Escape 검사', '금일 주요 업무: 제목 부분 검색 LIKE Escape 검사. 작업 배경은 %와 _ 포함 질의이며, 수행한 활동은 이스케이프 결과 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: SQL Injection 차단. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-01', '이스케이프 결과 확인 완료, 검토 결과 공유', ''),
    (49, 'Prompt 활성 버전 정합성 검토', '금일 주요 업무: Prompt 활성 버전 정합성 검토. 작업 배경은 v1/v2 이력 비교이며, 수행한 활동은 본문·포인터 일치 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 전환 API 구현. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-02', '본문·포인터 일치 확인 완료, 검토 결과 공유', ''),
    (50, 'API Status Code 명세 검토', '금일 주요 업무: API Status Code 명세 검토. 작업 배경은 404·422·503 구분이며, 수행한 활동은 표준 에러 포맷 정리이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 클라이언트 문서 갱신. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-03', '표준 에러 포맷 정리 완료, 검토 결과 공유', '클라이언트 문서 갱신; 조치 예정'),
    (51, 'DB Index 적용 전후 EXPLAIN 기록', '금일 주요 업무: DB Index 적용 전후 EXPLAIN 기록. 작업 배경은 단순 키워드 조회이며, 수행한 활동은 실행계획 차이 기록이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 필요 인덱스 검토. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-04', '실행계획 차이 기록 완료, 검토 결과 공유', ''),
    (52, '벡터 조회 지연 시간 측정', '금일 주요 업무: 벡터 조회 지연 시간 측정. 작업 배경은 요청 20회 반복이며, 수행한 활동은 중앙값 지연 계산이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 모델 초기화 분리. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-05', '중앙값 지연 계산 완료, 검토 결과 공유', ''),
    (53, 'Swagger와 Postman 문서 정합 확인', '금일 주요 업무: Swagger와 Postman 문서 정합 확인. 작업 배경은 endpoint 비교이며, 수행한 활동은 요청 필드 차이 0건이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 환경 변수 통일. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-06', '요청 필드 차이 0건 완료, 검토 결과 공유', ''),
    (54, '업무 보고서 작성자 정규화 검토', '금일 주요 업무: 업무 보고서 작성자 정규화 검토. 작업 배경은 author 문자열 점검이며, 수행한 활동은 공백·길이 제약 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 사용자 테이블 후속 검토. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-07', '공백·길이 제약 확인 완료, 검토 결과 공유', '사용자 테이블 후속 검토; 조치 예정'),
    (55, '벡터 재색인 재실행 검증', '금일 주요 업무: 벡터 재색인 재실행 검증. 작업 배경은 동일 개요 2회 인덱싱이며, 수행한 활동은 중복 벡터 0건 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 해시 비교. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-08', '중복 벡터 0건 확인 완료, 검토 결과 공유', ''),
    (56, 'Agent 실행 이력 마스킹 점검', '금일 주요 업무: Agent 실행 이력 마스킹 점검. 작업 배경은 민감 입력 시연이며, 수행한 활동은 로그에서 키 제거 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 수집 항목 최소화. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-09', '로그에서 키 제거 확인 완료, 검토 결과 공유', ''),
    (57, '모의 장애 상황 테스트 작성', '금일 주요 업무: 모의 장애 상황 테스트 작성. 작업 배경은 DB 연결 실패 주입이며, 수행한 활동은 503 응답 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 원인 안내 개선. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-10', '503 응답 확인 완료, 검토 결과 공유', ''),
    (58, '분류별 보고서 목록 화면 검토', '금일 주요 업무: 분류별 보고서 목록 화면 검토. 작업 배경은 카테고리 필터 API이며, 수행한 활동은 페이징 20건 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 정렬 조건 보완. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-11', '페이징 20건 확인 완료, 검토 결과 공유', '정렬 조건 보완; 조치 예정'),
    (59, '요약 응답 길이 제한 실험', '금일 주요 업무: 요약 응답 길이 제한 실험. 작업 배경은 max_sentences 변경이며, 수행한 활동은 문장 수 검증이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 원문 인용 주의. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-12', '문장 수 검증 완료, 검토 결과 공유', ''),
    (60, '일일 통합 프로젝트 배포 점검', '금일 주요 업무: 일일 통합 프로젝트 배포 점검. 작업 배경은 ZIP 무결성 검사이며, 수행한 활동은 환경 파일 목록 확인이다. 진행 상황: 결과를 담당자와 검토했고 관련 코드와 로그의 변경 사항을 기록했다. 발견 사항: 수강생 안내 준비. 외부 서비스 오류와 재현 가능한 로컬 오류를 구분하였다. 내일 계획: 미완료 항목을 재현하고 테스트 증거를 보강해 공유한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '2026-11-13', '환경 파일 목록 확인 완료, 검토 결과 공유', '')
INSERT INTO research_plans (report_id, title, content, author, create_at, update_at, research_goal, methodology, target_date) VALUES
    (61, '불균형 분류 모델의 공정성 평가 계획', '연구 배경: 불균형 분류 모델의 공정성 평가 계획의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 소수 클래스 오류 원인 조건에서 Macro-F1와 클래스별 Recall를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 교차 검증 설계. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '불균형 분류 모델의 공정성 평가 계획의 효과를 지표로 검증', '소수 클래스 오류 원인에서 기준선과 Macro-F1와 클래스별 Recall를 비교하고 교차 검증 설계를 점검', '2026-12-02'),
    (62, '멀티모달 OCR 성능 평가 연구 계획', '연구 배경: 멀티모달 OCR 성능 평가 연구 계획의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 표·문단 혼합 문서 조건에서 WER와 구조 보존율를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 오류 데이터 수집. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '멀티모달 OCR 성능 평가 연구 계획의 효과를 지표로 검증', '표·문단 혼합 문서에서 기준선과 WER와 구조 보존율를 비교하고 오류 데이터 수집를 점검', '2026-12-03'),
    (63, 'RAG 근거 인용 정확도 향상 계획', '연구 배경: RAG 근거 인용 정확도 향상 계획의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 출처 ID 매핑 조건에서 근거 포함률 지표를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 다중 문서 평가. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', 'RAG 근거 인용 정확도 향상 계획의 효과를 지표로 검증', '출처 ID 매핑에서 기준선과 근거 포함률 지표를 비교하고 다중 문서 평가를 점검', '2026-12-04'),
    (64, 'Vector Search 임계값 설정 연구', '연구 배경: Vector Search 임계값 설정 연구의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 관련·무관 질문 조건에서 Precision·Recall 곡선를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: Threshold 보정. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', 'Vector Search 임계값 설정 연구의 효과를 지표로 검증', '관련·무관 질문에서 기준선과 Precision·Recall 곡선를 비교하고 Threshold 보정를 점검', '2026-12-05'),
    (65, 'LLM Hallucination 감소 실험 계획', '연구 배경: LLM Hallucination 감소 실험 계획의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 근거 없는 질문 조건에서 정답 회피율 측정를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 인간 검토 기준. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '박분석', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', 'LLM Hallucination 감소 실험 계획의 효과를 지표로 검증', '근거 없는 질문에서 기준선과 정답 회피율 측정를 비교하고 인간 검토 기준를 점검', '2026-12-06'),
    (66, 'Agent Tool Calling 안전성 연구', '연구 배경: Agent Tool Calling 안전성 연구의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 허용 도구 목록 조건에서 잘못된 호출 차단율를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 최대 호출 횟수 제한. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '최기획', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', 'Agent Tool Calling 안전성 연구의 효과를 지표로 검증', '허용 도구 목록에서 기준선과 잘못된 호출 차단율를 비교하고 최대 호출 횟수 제한를 점검', '2026-12-07'),
    (67, '보고서 버전 변경 추적 연구', '연구 배경: 보고서 버전 변경 추적 연구의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 동일 문서 개정 조건에서 Revision 충돌 측정를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 롤백 시나리오. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '정실무', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '보고서 버전 변경 추적 연구의 효과를 지표로 검증', '동일 문서 개정에서 기준선과 Revision 충돌 측정를 비교하고 롤백 시나리오를 점검', '2026-12-08'),
    (68, '메타데이터 필터 적용 효과 연구', '연구 배경: 메타데이터 필터 적용 효과 연구의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 카테고리별 검색 조건에서 필터 전후 정확도를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 실패 원인 분석. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '한데이터', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', '메타데이터 필터 적용 효과 연구의 효과를 지표로 검증', '카테고리별 검색에서 기준선과 필터 전후 정확도를 비교하고 실패 원인 분석를 점검', '2026-12-09'),
    (69, 'Embedding 언어별 검색 성능 연구', '연구 배경: Embedding 언어별 검색 성능 연구의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 한글·영문 질의 조건에서 Top-k 적중률 비교를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 도메인 편향 확인. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '김연구', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', 'Embedding 언어별 검색 성능 연구의 효과를 지표로 검증', '한글·영문 질의에서 기준선과 Top-k 적중률 비교를 비교하고 도메인 편향 확인를 점검', '2026-12-10'),
    (70, 'Prompt 길이와 비용 분석 연구', '연구 배경: Prompt 길이와 비용 분석 연구의 효과를 기존 개발 환경에 적용해 확인할 필요가 있다. 연구 목표: 요약 유형 3개 조건에서 토큰량·지연 비교를 측정한다. 방법론: 기준선과 비교군을 나누고 동일한 평가 자료를 반복 활용한다. 정량 평가: 정확도 및 실패 건수 외에 운영 비용을 함께 기록한다. 위험 및 한계: 비용 상한 설정. 연구 종료 후 검증 결과와 재현 절차를 공개한다.', '이개발', '2026-11-19 09:00:00+09', '2026-11-19 09:00:00+09', 'Prompt 길이와 비용 분석 연구의 효과를 지표로 검증', '요약 유형 3개에서 기준선과 토큰량·지연 비교를 비교하고 비용 상한 설정를 점검', '2026-12-11'),
